#!/usr/bin/env bash
# recipes/crate-system-configuration-sys--0-5-0/build.sh -- stage the system-configuration-sys 0.5.0 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/system-configuration-sys-0.5.0"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
