# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"a75fb188eb626b924683e3b95e3a48e63551fcfb51949de2f06a9d91dbee93c9"}\n' > "${dest}/.cargo-checksum.json"
